export const BRAIN_SEARCHARCHIVE_COMMAND_DESCRIPTION = "Search Brain memory when the user asks to recall prior sessions, past decisions, archived context, previous files, or something already discussed. This is a strict two-phase CodeAct: first emit bare /searcharchive_ to receive SEARCHARCHIVE_TEMPLATE_RESULT, then fill that template exactly and include template_proof_hash before execution. Do not use for fresh web search or current file/project work." as const;
export const BRAIN_RENAME_SESSION_COMMAND_DESCRIPTION = "Rename the current chat session with exactly one internal prefix tag /rename_session_<short title>_ at the start of the first assistant response. The app strips the tag before display and uses the title everywhere the session name appears. The event is internal: never mention, explain, echo, format or discuss the rename in visible prose. Use a relevant, grammatically correct 2-5 word title." as const;
export const BRAIN_WEBSEARCH_COMMAND_DESCRIPTION = "Use /websearch_ for fresh sourced answers, URL discovery, verification, simple comparisons, recent facts or visual enrichment. This is a strict two-phase CodeAct: first emit bare /websearch_ to receive WEBSEARCH_TEMPLATE_RESULT, then fill the compact template exactly and include template_proof_hash before execution. WEBSEARCH_RESULT returns a real web-search manifest: answer, citations, ranked URLs, provider trace, suggested scraper URLs and optional media candidates; no raw pages or downloads. Treat WEBSEARCH_RESULT as sufficient when the answer, citations and ranked URLs satisfy the user. Set next=answer_only for direct sourced answers, quick verification, latest status checks, simple comparisons or URL lists. Set next=scrape_urls only when the next loop truly needs /scrapers_ to consult selected pages for Markdown, tables, structured source data, media artifact URLs, screenshots or PDFs. In visible prose, say that sources are being searched, checked, opened, consulted or validated; never say extraction profonde, deep extraction, scraping internals, or expose scraper implementation details. Set media=images or media=video_audio only when visuals/media source pages would improve the answer. Prefer over /googleweb_ for cited answers; respect attribution, privacy, paywalls and budget." as const;
export const BRAIN_CODEDOCS_COMMAND_DESCRIPTION = "Use /codedocs_ to query Context7 MCP for current, version-aware library/API documentation, setup instructions and code examples before coding against external dependencies. Prefer it after /codingbrain_ and before guessing imports, configuration, API signatures, migration steps or framework behavior. It is read-only documentation retrieval, not general web search and not page scraping; use /websearch_ first when the library, package or official docs URL is unknown." as const;
export const BRAIN_GITHUB_MCP_COMMAND_DESCRIPTION = "Use /github_ for GitHub MCP workflows on remote repositories: repo context, code search, issues, pull requests, Actions/CI, releases and PR discussion triage. Prefer read-only operations by default; issue/PR comments, labels, branch changes or other writes require explicit user confirmation and a scoped GitHub token. Use local workspace actions for files already on disk." as const;
export const BRAIN_WEBACT_COMMAND_DESCRIPTION = "Use /webact_ for Playwright MCP browser automation when the task needs page interaction rather than a source-backed search answer: navigate, snapshot, click, type, screenshot, evaluate or verify a user flow. Prefer it for live web app testing, forms and visual checks. Never submit purchases, account changes, messages or sensitive forms without explicit user confirmation." as const;
export const BRAIN_SECURITYSCAN_COMMAND_DESCRIPTION = "Use /securityscan_ for Semgrep MCP security and static-analysis checks on code paths or snippets, especially before commits, PRs, generated code, dependency-facing adapters, auth, filesystem, shell, network or deserialization changes. It returns a compact SECURITYSCAN_RESULT with findings and evidence; do not treat a clean scan as a full proof of security." as const;
export const BRAIN_GOOGLEWEB_COMMAND_DESCRIPTION = "Open contained WebExplorer on a generic Google search when the user wants to visually browse or manually inspect web results. Prefer /websearch_ when the assistant must answer with cited sources, discover URLs, rank sources, verify current information or feed /scrapers_. Do not use for Gmail, Airbnb/travel lodging, image generation/editing, or local workspace work." as const;
export const BRAIN_GOOGLEPLACE_COMMAND_DESCRIPTION = "Verify a very specific or ambiguous public place, business, administration or street address through Google Places only when the LLM needs an authoritative place_id/address/coordinate check before /maps_. Skip /googleplace_ and go directly to /maps_ when the requested address, city, country, known landmark, GPS coordinate or broad geographic target is already specific enough for the LLM to fill the Maps template. This is read-only: return place_id, normalized name/address, Google types, WGS84 coordinates and proof hash; do not open a visual map, choose camera settings or use saved/device location." as const;
export const BRAIN_SCRAPERS_COMMAND_DESCRIPTION = "Use /scrapers_ only after URLs are known and WEBSEARCH_RESULT is not enough: collect clean Markdown, structured fields, links, media URLs/captions, screenshots/PDF/MHTML/download refs and provenance. Do not call it reflexively after every /websearch_; a sourced answer, verification, ranked URL list or light media manifest can finish at WEBSEARCH_RESULT. Runs Scrapling MCP + Crawl4AI MCP in parallel and returns one compact SCRAPERS_RESULT/media_manifest for RAG, memory, research, monitoring or visual conversation enrichment. In visible prose, describe this as consulting, opening, checking or validating sources; never say extraction profonde, deep extraction, scraping internals, or expose scraper implementation details. Scrapling selector/session/screenshot needs are handled inside this same command; do not expose a second Scrapling CodeAct. Respect robots/terms/rate limits/privacy; stealth only for authorized targets." as const;
export const BRAIN_MAPS_COMMAND_DESCRIPTION = "Open the fixed Cesium Google Photorealistic 3D Tiles view only for explicit map/localization/route/coordinates/where-is/local-weather/Google Earth intent. Go directly to /maps_ when the address, known landmark, city, country, broad geographic target or GPS coordinates are already specific enough; call /googleplace_ first only for very specific or ambiguous public places, businesses, administrations or street addresses that need authoritative verification before the Maps template is filled. A place name in a cultural, historical, literary, vocabulary, table or explanation request is not enough; use /websearch_ then /scrapers_ for source/media enrichment. Bare /maps_ returns MAPS_TEMPLATE_RESULT or opens a neutral Earth view, never the saved home city. The camera is host-fixed and never an agent slot. Never read device location without explicit permission." as const;
export const BRAIN_GMAIL_COMMAND_DESCRIPTION = "Use /gmail_ for all Gmail tasks: search, inspect, summarize, draft or prepare replies through the Gmail API bridge, or open Gmail visually when intent=open and mode=split_webexplorer. Use /gmail_ whenever the user asks about their mailbox, emails, Gmail messages, attachments, unread mail, senders, subjects, invoices, confirmations, appointments, or asks to draft/reply to an email. Choose intent=search or intent=summarize with mode=gmail_api for checking, reading, reporting, new/unread/incoming mail, or s'il y a du nouveau, even when the user says open/ouvre la boite mail; choose intent=open only for visual Gmail navigation without mailbox analysis. This is a strict two-phase CodeAct: first emit bare /gmail_ to receive GMAIL_TEMPLATE_RESULT, then fill the compact returned template with template_proof_hash before execution. Default mode=gmail_api returns GMAIL_RESULT with auth_required until user OAuth is connected, then bounded Gmail REST results using the narrowest official scope: gmail.metadata for metadata-only listings, gmail.readonly for search/read, gmail.compose for drafts, gmail.send only after explicit user-approved sending. Visible prose must stay short and user-facing: say that recent mail is being checked; do not mention templates, CodeAct, API bridge, dedicated access, authorization, or result lists before GMAIL_RESULT. Mention authorization only when GMAIL_RESULT status=auth_required. Never send automatically, never use /googleweb_ for Gmail, never expose OAuth tokens, and never expose private mail content unless the user explicitly asked for that mailbox action." as const;
export const BRAIN_AIRBNB_COMMAND_DESCRIPTION = "Use Airbnb after /maps_ when a geographic place is detected together with travel/vacation/stay language: voyage, vacances, partir, visiter, tourisme, sejour, destination, dates, guests, lodging, accommodation, hotel-like stay, home/apartment rental, vacation rental, booking, budget for stays, or short-term stay search. Do not use for city facts, local weather, geography, maps, or routes without travel/vacation/stay intent." as const;
export const BRAIN_NEWIMAGE_COMMAND_DESCRIPTION = "Generate a brand-new image from a text prompt: draw, create, render, imagine, make a logo/poster/scene/asset. Do not use /workspace_; no local project folder is required." as const;
export const BRAIN_EDITIMAGE_COMMAND_DESCRIPTION = "Edit an existing image attached, selected, or visible in the conversation: retouch, remove/add/replace elements, change colors/background/style, crop, upscale, or transform. Prefer over /workspace_; do not answer with an external-tool prompt." as const;
export const BRAIN_QUESTIONNAIRE_COMMAND_DESCRIPTION = "Ask a short paginated questionnaire in the user's current language when the user goal is clear but key choices, constraints, scope, files, risks, output style or success criteria are missing. Use it before acting if guessing would hurt the result. In Trading Brain, a vague chart request like analyse le graphique needs /questionnaire_ before /chart_ unless the user explicitly asks for a quick/default read. Max 5 questions, one per page, three concrete expert options each; host adds Other. Skip trivial tasks or obvious safe defaults." as const;
export const BRAIN_PLAN_COMMAND_DESCRIPTION = "Open the Plan panel when a non-trivial task needs a visible multi-step action plan before or during execution. Use for ordered steps, milestones, dependencies, verification gates, or progress structure. Keep it concise and actionable: title, optional context, 2-8 concrete steps, current focus, and stop condition. Do not use for one-step answers, tiny edits, or vague brainstorming." as const;
export const BRAIN_SCIENCE_COMMAND_DESCRIPTION = "Mandatory first action while the active Brain is general and the LLM understands that the user's task belongs to science, engineering, mathematics, biology, chemistry, physics, cryptography, formal analysis, electronics, mechanics, robotics, CAD/3D engineering, physical product/prototype engineering, Banger, Monster, /newcompute_ or future Banger 3D work. Do not use only for looking at images of artworks, sculptures, ceramics, forms, style, composition or aesthetics; those stay in General Brain unless the user asks for material science, structure, manufacturing, CAD, simulation, measurements or engineering constraints. Activate /sciencebrain_ before questionnaire or specialized answer; after activation, use the injected science brain catalog." as const;
export const BRAIN_CODING_COMMAND_DESCRIPTION = "Mandatory first action while the active Brain is general and the LLM understands that the user's task belongs to software engineering, coding, websites, applications, repositories, debugging, refactoring, tests, architecture, scripts, Rust/TypeScript/Electron, APIs, build systems, or developer tooling. Activate /codingbrain_ before the specialized answer; do not paste implementation code in the same Brain-switch message. After activation, continue through the normal action cycle with the injected coding brain catalog and local action tools." as const;
export const BRAIN_TRADING_COMMAND_DESCRIPTION = "Mandatory first action while the active Brain is general and the LLM understands that the user's task belongs to trading, brokerage, OANDA, market orders, positions, stops, take-profit, margin, financing, price feeds, chart trading, order history or broker execution. Activate /tradingbrain_ before the specialized answer; do not send or prepare live orders in the same Brain-switch message. After activation, continue through the injected Trading Brain catalog and safety-gated trading CodeActs." as const;
export const BRAIN_NEWBRAIN_COMMAND_DESCRIPTION = "Create a new specialized Brain scope for a durable domain such as marketing, trading, immobilier, science-notes or another recurring work area. Use only after the LLM has reasoned that repeated lessons, rules, skills, tasks or CodeAct drafts would pollute unrelated sessions if stored in a broad scope. This command never targets the root read-only catalog and cannot add commands there. When this command is emitted with an explicit brain_name, the host automatically derives a specialized activator CodeAct such as /musicianbrain_ in the specialized Brain registry and seeds /local_actions_ so the specialized Brain can discover local AgentAction JSON routes. The LLM chooses the domain, title, purpose, activation triggers, initial lesson/rule/skill/task/CodeAct categories and compact token budget; the host records the explicit fields and must not semantically infer the domain." as const;
export const BRAIN_MODIFY_NAMED_BRAIN_COMMAND_DESCRIPTION = "Modify an existing specialized Brain named in the command form /modify\\\"<brain_name>\\\"brain_. Use when the LLM has a user-confirmed or strong candidate learning that belongs to that named Brain: observed error converted into replacement rule, conduct rule, reusable skill, follow-up task or CodeAct draft. This command targets only named specialized Brain scopes and never the root read-only catalog. The LLM supplies the brain_name, entry kind, evidence/observation, replacement rule when an error is being fixed, trigger, exceptions and compact content; the host only validates, stores and reinjects the explicit update." as const;
export const BRAIN_WORKSPACE_COMMAND_DESCRIPTION = "Ask the user to choose a local project/workspace folder only for coding, repository, filesystem, build, script, or project-file work. Never use for web, Gmail, Airbnb, Brain memory, image generation, or image editing." as const;
export const BRAIN_LOCAL_ACTIONS_COMMAND_DESCRIPTION = "Call the local AgentAction JSON atlas as a Brain CodeAct when a task may involve the computer, files, apps, browser, documents, code, Git, cloud CLIs, virtualization, Windows settings, packages or automation and the exact local route is not already obvious. Executable form: /local_actions_ scope=\\\"all|workspace|computer|coding|browser|documents|windows|cloud|automation\\\" query=\\\"short task/topic\\\" maxResults=\\\"40\\\". The host maps this read-only CodeAct to AGENT_ACTION_JSON {\\\"action\\\":\\\"capabilities\\\"}, returns LOCAL_ACTIONS_RESULT with available actions, risky/blocked/planned boundaries, fallback routes and proof hashes, then the LLM chooses the next CodeAct or concrete AGENT_ACTION_JSON action." as const;
export const BRAIN_CODING_LIVE_PREVIEW_COMMAND_DESCRIPTION = "Open the live coding preview canvas for a visual coding artifact that already exists on disk. Use only while Coding Brain is active, only after creating or modifying a real local HTML/CSS/JS/React/Vite visual file with AGENT_ACTION_JSON and verifying the absolute file path. Immediately before this CodeAct, write one short natural paragraph explaining that the visual preview is being opened in the conversation so the user can watch the result. Required slot: path=\\\"absolute-local-file\\\". Optional slot: kind=\\\"html|react|vite\\\". Never use for backend-only scripts, prose-only snippets, or unverified code blocks." as const;
export const BRAIN_NEWCOMPUTE_COMMAND_DESCRIPTION = "Start a new typed Monster compute when the user needs heavy/local math, simulation, numeric analysis, tensors, optimization, batch calculation, or verifiable compute artifacts rather than a normal prose answer." as const;
export const BRAIN_SELECTCOMPUTE_COMMAND_DESCRIPTION = "Reuse a saved compute from the Brain compute library when the user wants to rerun, adapt, compare, or continue a previous/saved compute instead of defining a new one." as const;
export const BRAIN_NAMED_COMPUTE_COMMAND_DESCRIPTION = "Invoke a promoted named compute specialization when the user names or clearly matches a known compute pattern. Use after the named compute exists; otherwise start with /newcompute_." as const;
export const BRAIN_NEWOBJECT_COMMAND_DESCRIPTION = "Create or modify a Banger 3D/object contract from an explicit object, scene, SDF, geometry, material, or computational-design request. Do not use for 2D image editing." as const;
export const BRAIN_WEB_COMMAND_DESCRIPTION = "Run bounded web research through the contained web peripheral for research/navigation workflows not owned by Gmail, Airbnb, or Google-specific search. Never make browser content the global app shell." as const;
export const BRAIN_FRONTDESIGN_COMMAND_DESCRIPTION = "Change the app display colors or color palettes when the user asks. Use only for visual color/theme changes, not general coding or image generation." as const;
export const BRAIN_GOOGLE_AGENDA_COMMAND_DESCRIPTION = "Prepare a Google Calendar action when the user asks to create, inspect, or plan calendar events with dates, times, attendees, reminders, or schedule details. Execution stays user-confirmed." as const;
export const BRAIN_BRAIN_COMMAND_DESCRIPTION = "Operate on Brain-owned registries: save/recall/update user-confirmed memory, promote procedural knowledge, inspect Brain state, or reason about Brain rules. Never patch the root CodeAct catalog. Not for ordinary user tasks." as const;
export const BRAIN_NEWMODULE_COMMAND_DESCRIPTION = "Create a new narrow module contract when the user wants a new app/module integration or sidebar capability. Define the module before adding broad implementation surface." as const;
export const BRAIN_RUST_PORT_ADAPTER_COMMAND_DESCRIPTION = "Prepare a Rust service adapter for an external service, vertical capability, native bridge, or backend integration behind a narrow typed interface." as const;
export const BRAIN_RUST_STATE_STORE_COMMAND_DESCRIPTION = "Prepare a Rust-owned durable state store for local service state, caches, indexes, credentials metadata or persistent domain data with explicit schema and ownership." as const;
export const BRAIN_CHART_COMMAND_DESCRIPTION = "Use /chart_ when the next answer needs evidence from the active Trading chart: instrument, timeframe, recent candles, trend, volatility, support/resistance, indicators, or SL/TP placement. First call bare /chart_ to get CHART_TEMPLATE_RESULT, then fill the returned template with timeframe, candle_count, screenshot and OHLC needs. For any chart-analysis request, /chart_ is the mandatory read step; after CHART_RESULT, use /edit_chart_ before the final analysis whenever the answer discusses candles, levels, trendlines, support/resistance, indicators, risk zones or SL/TP. Do not use /chart_ for account/order execution, news, broker history, or general market facts. CHART_RESULT is final chart evidence for the next step." as const;
export const BRAIN_EDIT_CHART_COMMAND_DESCRIPTION = "Use /edit_chart_ to make chart reasoning visible on the active Trading chart while the analysis is happening. It is mandatory after /chart_ for chart-analysis requests whenever the answer relies on candles, trend, support/resistance, breakout/rejection zones, indicators, risk zones, SL/TP or order levels. First call bare /edit_chart_ to get EDIT_CHART_TEMPLATE_RESULT, then fill typed actions: select_candles, ray, horizontal_line, vertical_line, moving_average, vwap, donchian_channel or clear. Emit /edit_chart_ immediately after the sentence that explains why you need that visual element; do not wait to batch all annotations at the end. Prefer one conceptual edit per call unless one reasoning step needs coupled elements. Give each created element a short label; after EDIT_CHART_RESULT, cite returned elements with clickable *label* or ^label^ tags. EDIT_CHART_RESULT is renderer proof: applied/refused actions, element IDs, tags and proof_hash." as const;
export const BRAIN_MARKET_ORDER_COMMAND_DESCRIPTION = "Use /market_order_ when the user wants to prepare, stage, send, close, or reduce an OANDA market order, or validate exact SL/TP/trailing values in the Order window. Do not use it for analysis-only answers, news, chart commentary, pending/limit orders, vague trade ideas, or missing intent/instrument/side/size/risk/confirmation; ask first. First call bare /market_order_ to get MARKET_ORDER_TEMPLATE_RESULT from the Order window, then fill the returned template exactly. If unitsAvailable is present, units must be <= max_units_after_1pct_buffer; never use the full unitsAvailable value. Default to execution_mode=stage_only and user_confirmation=none. Live execution requires explicit user confirmation of the exact order, then execution_mode=live_oanda_order and user_confirmation=user_confirmed_live_order. MARKET_ORDER_RESULT is final broker proof: executed/rejected/staged, transaction IDs, rejectReason, order_visibility and proof_hash." as const;
export const BRAIN_SCIENCE_VISIBLE_CATALOG = "SCIENCE_ENGINEERING_3D_BRAIN v1\\nPurpose: active session catalog for scientific reasoning, mathematics, statistics, biology, chemistry, physics, cryptography, optimization, formal analysis, engineering, robotics, physical prototypes, CAD/3D conception, Banger objects, future Banger 3D work, Monster compute, simulation and verified design.\\nUse /local_actions_ when scientific/engineering work may require local files, apps, instruments, browser, documents, shell, Banger/Forge workspace, installed CLIs or Windows automation and the exact executable route is not obvious.\\nUse /questionnaire_ when key scientific, engineering, constraint, scope, risk or success-criteria choices are missing.\\nUse /plan_ when the work needs a visible multi-step action plan, milestones, ordering or progress structure.\\nUse /newcompute_ for any heavy/verifiable compute: math, physics, biology models, chemistry calculations, cryptography analysis, optimization, simulation, numerical analysis, sizing, performance envelopes, statistical analysis or proof artifacts.\\nUse /newobject_ for 3D/Banger object, geometry, SDF, CAD-like part, scene, material, assembly or computational design requests.\\nUse /websearch_ when current external research is needed for papers, standards, datasheets, components, protocols, biological references or scientific sources; use /googleweb_ only for visual browsing.\\nUse /workspace_ only if actual local project/code/files are needed; scientific discussion, calculations, cryptography reasoning, biology reasoning, image work and 3D conception do not need a workspace.\\nPrefer explicit assumptions, constraints, units, safety margins, verification plans, reproducible calculations and artifact/proof summaries." as const;
export const BRAIN_CODING_VISIBLE_CATALOG = "CODING_BRAIN v1\\nPurpose: active session catalog for software engineering, repositories, debugging, implementation, tests, refactors, architecture, scripts, build systems, APIs, Rust, TypeScript, Electron and developer tooling.\\nUse /local_actions_ when coding work may need local files, project commands, browser, Git/GitHub, packages, CI, virtualization, shell, Windows tools or a visual preview route and the exact executable action is not obvious.\\nUse /questionnaire_ when key product, scope, file, risk, style, stack or success-criteria choices are missing.\\nUse /plan_ when the coding task needs a visible multi-step action plan, milestones, ordering, verification gates or progress structure.\\nUse /workspace_ when local repository or filesystem access is required before coding, running tests or inspecting files.\\nWindows/local action tools remain available in Coding Brain for repo inspection, file edits, searches, build/test commands, browser checks and shell work: use /local_actions_ for route discovery, then use AGENT_ACTION_JSON only for real execution and wait for AGENT_ACTION_RESULT before claiming success.\\nFor requests to code, build or create a visual page/component/site/app, create or modify a real local file first through AGENT_ACTION_JSON, verify it exists, write one short natural paragraph saying that the live visual is opening in the conversation, then emit /coding_live_preview_ path=\\\"...\\\" kind=\\\"html|react|vite\\\" so the Canvas can show the live visual. Do not answer with only a code block, copy-paste instructions, or \\\"put this in a file\\\" unless the user explicitly asks for a snippet only.\\nUse /websearch_ for current docs, releases, APIs, dependency behavior, GitHub project discovery, package comparisons and source-backed technical research before implementing; use /scrapers_ after URLs are known and the selected source pages must be consulted more closely.\\nUse /codedocs_ for Context7 current library/API docs once the dependency is identified; use /github_ for remote GitHub repo/issues/PR/CI/release work; use /webact_ for Playwright browser interaction and visual verification; use /securityscan_ for Semgrep checks before risky code commits or PRs.\\nUse /searcharchive_ to recall prior project decisions, previous bugs, existing architecture notes or earlier implementation context.\\nUse /newmodule_ when the user wants a new app/module integration or new product capability before broad implementation.\\nUse /rust_port_adapter_ for external services, native bridges or backend adapters behind narrow Rust interfaces.\\nUse /rust_state_store_ for durable state, caches, indexes, credentials metadata or persistent domain data.\\nUse /newcompute_ only for heavy/verifiable computation inside coding workflows, not for ordinary code edits.\\nDo not use /workspace_ for image generation/editing, Gmail, Airbnb or pure web research." as const;
export const BRAIN_TRADING_VISIBLE_CATALOG = "TRADING_BRAIN v1\\nPurpose: active session catalog for broker-connected trading, OANDA, NATGAS, chart trading, market orders, pending orders, positions, SL/TP, trailing stops, margin, financing, order history, broker transactions and live price feeds.\\nUse /questionnaire_ before /chart_ when a chart request is underspecified: bare analyse le graphique, missing objective, horizon/timeframe, output style, decision need, risk context or trade-vs-observation intent. Ask only the missing choices; skip it when the user explicitly asks for a quick/default read or already gave enough context.\\nUse /chart_ when the next answer needs active-chart evidence: instrument, timeframe, recent candles, trend, volatility, support/resistance, indicators, risk zones or SL/TP placement. For chart-analysis requests with enough context, first emit bare /chart_ and wait for CHART_TEMPLATE_RESULT; then fill timeframe, candle_count, screenshot and OHLC needs. CHART_RESULT is final chart evidence for the next step.\\nUse /edit_chart_ during the analysis, not as a final batch. After CHART_RESULT, whenever your reasoning decides to add a VWAP/MA/Donchian, check a candle break, mark a level, draw a ray, select candles, or show SL/TP/order zones, write one short visible sentence explaining that step, then immediately emit /edit_chart_. First emit bare /edit_chart_ and wait for EDIT_CHART_TEMPLATE_RESULT; then fill typed actions with short labels. Prefer one conceptual edit per call. After EDIT_CHART_RESULT, cite returned elements with clickable *label* or ^label^ tags.\\nUse /market_order_ when the user wants to prepare, stage, send, close, or reduce an OANDA market order, or validate exact Order-window SL/TP/trailing execution. Do not use it for analysis-only answers, news, chart commentary, pending/limit orders, vague trade ideas, or missing intent/instrument/side/size/risk/confirmation; ask first.\\nProtocol for /market_order_: first emit bare /market_order_ and wait for MARKET_ORDER_TEMPLATE_RESULT from the Order window, then fill the returned template exactly. If unitsAvailable is present, units must be <= max_units_after_1pct_buffer = floor(side-specific unitsAvailable * 0.99), never the full unitsAvailable value. Default to execution_mode=stage_only and user_confirmation=none. Live execution requires explicit user confirmation of exact instrument, side, units, SL/TP/trailing and account, then execution_mode=live_oanda_order and user_confirmation=user_confirmed_live_order. MARKET_ORDER_RESULT is final broker proof: executed/rejected/staged, transaction IDs, rejectReason, order_visibility and proof_hash.\\nUse /questionnaire_ when order intent, size, risk, SL/TP, account, instrument, price freshness or confirmation is ambiguous.\\nUse /plan_ when a trading workflow needs multiple checks such as account state, position review, risk sizing and order staging.\\nUse /websearch_ only for current external broker documentation, market-source verification or regulatory/source-backed facts; do not use web search as a broker execution path.\\nNever expose OANDA tokens, never infer a live order from vague language, never execute without explicit user confirmation, and always return broker transaction IDs/proof hashes after execution." as const;

